export const UNREACHABLE = Number.POSITIVE_INFINITY;

/** Direction from a cell toward one of its 4-neighbors. */
export type Direction = 'up' | 'down' | 'left' | 'right';

export interface FlowField {
  width: number;
  height: number;
  /** Integration cost per cell (BFS distance to goal). UNREACHABLE if not reachable. */
  integration: Float64Array;
  /** Flow direction per cell, or null for goal / unreachable / walls. */
  direction: (Direction | null)[];
}

interface Point {
  x: number;
  y: number;
}

function parseMap(map: string[]): { grid: string[][]; width: number; height: number; goal: Point } {
  const height = map.length;
  const width = map[0].length;
  const grid = map.map((row) => row.split(''));
  let goal: Point | null = null;
  for (let y = 0; y < height; y++) {
    if (map[y].length !== width) throw new Error(`Row ${y} has inconsistent length`);
    for (let x = 0; x < width; x++) {
      const c = grid[y][x];
      if (c === 'G') {
        if (goal) throw new Error('Multiple goals');
        goal = { x, y };
      } else if (c !== '#' && c !== '-') {
        throw new Error(`Invalid character '${c}' at (${x}, ${y})`);
      }
    }
  }
  if (!goal) throw new Error('No goal G in map');
  return { grid, width, height, goal };
}

const DELTAS: [Direction, number, number][] = [
  ['up', 0, -1],
  ['down', 0, 1],
  ['left', -1, 0],
  ['right', 1, 0],
];

/**
 * Builds an integration field (BFS distance-to-goal) and a flow field
 * (direction to the lowest-cost open neighbor) from an ASCII map.
 * '#' = wall, '-' = open, 'G' = goal.
 */
export function buildFlowField(map: string[]): FlowField {
  const { grid, width, height, goal } = parseMap(map);
  const integration = new Float64Array(width * height).fill(UNREACHABLE);
  const direction: (Direction | null)[] = new Array(width * height).fill(null);

  // BFS from the goal over open cells.
  const queue: Point[] = [goal];
  integration[goal.y * width + goal.x] = 0;
  for (let head = 0; head < queue.length; head++) {
    const { x, y } = queue[head];
    const d = integration[y * width + x];
    for (const [, dx, dy] of DELTAS) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
      if (grid[ny][nx] === '#') continue;
      const idx = ny * width + nx;
      if (integration[idx] !== UNREACHABLE) continue;
      integration[idx] = d + 1;
      queue.push({ x: nx, y: ny });
    }
  }

  // Flow field: point at the neighbor with minimal integration cost.
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const idx = y * width + x;
      if (grid[y][x] === '#' || integration[idx] === UNREACHABLE) continue;
      if (x === goal.x && y === goal.y) continue; // goal has no outgoing direction
      let bestCost = integration[idx];
      let bestDir: Direction | null = null;
      for (const [dir, dx, dy] of DELTAS) {
        const nx = x + dx;
        const ny = y + dy;
        if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
        const nIdx = ny * width + nx;
        if (grid[ny][nx] === '#') continue;
        if (integration[nIdx] < bestCost) {
          bestCost = integration[nIdx];
          bestDir = dir;
        }
      }
      direction[idx] = bestDir;
    }
  }

  return { width, height, direction, integration };
}

export function idx(field: FlowField, x: number, y: number): number {
  return y * field.width + x;
}

