import { describe, expect, it } from 'vitest';
import { buildFlowField, idx, UNREACHABLE, type Direction } from '../src/flowfield';

const MAP = [
  '########',
  '#------#',
  '#-##-#-#',
  '#-#--#-#',
  '#----#G#',
  '########',
];

const STEP: Record<Direction, [number, number]> = {
  up: [0, -1],
  down: [0, 1],
  left: [-1, 0],
  right: [1, 0],
};

function goalOf(map: string[]): { x: number; y: number } {
  for (let y = 0; y < map.length; y++) {
    const x = map[y].indexOf('G');
    if (x !== -1) return { x, y };
  }
  throw new Error('no goal');
}

describe('flow field on the given map', () => {
  const field = buildFlowField(MAP);
  const goal = goalOf(MAP);
  const maxSteps = field.width * field.height;

  it('has correct dimensions and a finite integration value at G (0)', () => {
    expect(field.width).toBe(8);
    expect(field.height).toBe(6);
    expect(field.integration[idx(field, goal.x, goal.y)]).toBe(0);
  });

  it('every reachable open cell reaches G with strictly decreasing cost within width*height steps', () => {
    let reachableCount = 0;
    for (let y = 0; y < field.height; y++) {
      for (let x = 0; x < field.width; x++) {
        if (MAP[y][x] === '#') continue;
        const startCost = field.integration[idx(field, x, y)];
        if (startCost === UNREACHABLE) continue;
        reachableCount++;

        // Repeatedly follow the flow field.
        let cx = x;
        let cy = y;
        let cost = startCost;
        let steps = 0;
        while (!(cx === goal.x && cy === goal.y)) {
          expect(steps).toBeLessThan(maxSteps); // must terminate within width*height steps
          const dir = field.direction[idx(field, cx, cy)];
          expect(dir).not.toBeNull();
          const [dx, dy] = STEP[dir as Direction];
          cx += dx;
          cy += dy;
          expect(cx).toBeGreaterThanOrEqual(0);
          expect(cy).toBeGreaterThanOrEqual(0);
          expect(cx).toBeLessThan(field.width);
          expect(cy).toBeLessThan(field.height);

          const nextCost = field.integration[idx(field, cx, cy)];
          expect(nextCost).toBeLessThan(cost); // strictly decreasing integration cost
          cost = nextCost;
          steps++;
        }
        expect(cost).toBe(0);
      }
    }
    expect(reachableCount).toBeGreaterThan(0);
  });

  it('the goal cell itself has no direction', () => {
    expect(field.direction[idx(field, goal.x, goal.y)]).toBeNull();
  });

  it('integration costs match BFS distances to the goal', () => {
    // Spot-check: cell adjacent to the goal must have cost 1.
    const neighbors: [number, number][] = [
      [goal.x - 1, goal.y],
      [goal.x + 1, goal.y],
      [goal.x, goal.y - 1],
      [goal.x, goal.y + 1],
    ];
    const openNeighbors = neighbors.filter(([x, y]) => MAP[y]?.[x] === '-');
    expect(openNeighbors.length).toBeGreaterThan(0);
    for (const [x, y] of openNeighbors) {
      expect(field.integration[idx(field, x, y)]).toBe(1);
    }
    // Every open cell's flow target has exactly one less cost.
    for (let y = 0; y < field.height; y++) {
      for (let x = 0; x < field.width; x++) {
        const dir = field.direction[idx(field, x, y)];
        if (!dir) continue;
        const [dx, dy] = STEP[dir];
        const c = field.integration[idx(field, x, y)];
        const n = field.integration[idx(field, x + dx, y + dy)];
        if (c !== UNREACHABLE && n !== UNREACHABLE) {
          expect(n).toBeLessThan(c);
        }
      }
    }
  });
});

describe('unreachable cells', () => {
  // Second map with a walled-off pocket at row 2, cols 2-3 ('o o' enclosed by walls).
  const MAP_WITH_POCKET = [
    '########',
    '#------#',
    '#-##-#-#',
    '#-#--#-#',
    '#-oo-#G#', // 'o' marks the walled-off pocket interior
    '########',
  ].map((row) => row.replace(/o/g, '-')); // pocket is open '-' but sealed by walls

  it('flags unreachable open cells with UNREACHABLE sentinel and null direction', () => {
    const field = buildFlowField(MAP_WITH_POCKET);
    let unreachableFound = 0;
    for (let y = 0; y < field.height; y++) {
      for (let x = 0; x < field.width; x++) {
        if (MAP_WITH_POCKET[y][x] === '#') continue;
        const i = idx(field, x, y);
        const unreachable = field.integration[i] === UNREACHABLE;
        if (unreachable) {
          unreachableFound++;
          expect(field.direction[i]).toBeNull();
          // Verify it truly is sealed off: no reachable neighbor exists.
          for (const [dx, dy] of Object.values(STEP)) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx < 0 || ny < 0 || nx >= field.width || ny >= field.height) continue;
            if (MAP_WITH_POCKET[ny][nx] === '#') continue;
            expect(field.integration[idx(field, nx, ny)]).toBe(UNREACHABLE);
          }
        } else {
          // Reachable cells must have a direction unless they are the goal.
          const isGoal = MAP_WITH_POCKET[y][x] === 'G';
          if (!isGoal) expect(field.direction[i]).not.toBeNull();
        }
      }
    }
    // The pocket at (2..3, 4) must actually be detected as unreachable.
    expect(unreachableFound).toBe(2);
    expect(field.integration[idx(field, 2, 4)]).toBe(UNREACHABLE);
    expect(field.integration[idx(field, 3, 4)]).toBe(UNREACHABLE);
    expect(field.direction[idx(field, 2, 4)]).toBeNull();
    expect(field.direction[idx(field, 3, 4)]).toBeNull();
  });

  it('all reachable cells still reach G correctly in the pocket map', () => {
    const field = buildFlowField(MAP_WITH_POCKET);
    const goal = goalOf(MAP_WITH_POCKET);
    for (let y = 0; y < field.height; y++) {
      for (let x = 0; x < field.width; x++) {
        if (MAP_WITH_POCKET[y][x] === '#') continue;
        if (field.integration[idx(field, x, y)] === UNREACHABLE) continue;
        let cx = x;
        let cy = y;
        let steps = 0;
        while (!(cx === goal.x && cy === goal.y)) {
          expect(steps++).toBeLessThan(field.width * field.height);
          const dir = field.direction[idx(field, cx, cy)];
          expect(dir).not.toBeNull();
          const [dx, dy] = STEP[dir as Direction];
          cx += dx;
          cy += dy;
        }
      }
    }
  });
});

